    /**
     * Keep the URL's project base path ("/:projectName/…") in sync with the
     * active project. The unscoped "root" route is promoted to the scoped
     * home once a project is active. No-op when the URL already matches.
     *
     * IMPORTANT: this runs at the end of `activeProjectChanged`, so it must
     * never navigate away from a route that cannot express the project and
     * must never throw — a failing `router.replace` aborts the project switch.
     */
    syncRouteProjectPrefix(_, project) {
      const router = $storex.$router
      const current = router?.currentRoute?.value
      if (!router || !project?.project_name) return
      if (!current?.name || current.name === 'mobile') return

      // The desktop shell is a catch-all workspace route: its URL does not
      // carry the project, so replacing it with "/<project_name>" would leave
      // the desktop layout and reload the page. The active project lives in
      // the store, so there is nothing to sync here.
      if (current.name === 'codx-junior-split') return

      // Use the RAW project name: vue-router percent-encodes params while
      // building the URL, so encoding here would double-encode the segment and
      // break the reload lookup in restoreLastActiveProject(). Router params
      // are decoded, so the equality check below compares like values.
      const projectName = project.project_name
      const targetName = current.name === 'root' ? 'home' : current.name

      // Already scoped to the right project – nothing to do.
      if (current.name !== 'root' && current.params?.projectName === projectName) {
        return
      }

      // `resolve()` throws synchronously for an unknown route name, which
      // `.catch()` would not intercept: keep it contained.
      try {
        router.replace({
          name: targetName,
          params: { ...(current.params || {}), projectName },
          query: current.query
        })?.catch?.(() => {})
      } catch (ex) {
        console.warn('Cannot sync the URL with the active project', ex)
      }
    },
</file_change>

## Verification checklist

1. Pick another project in the sidebar → the shell stays mounted, chats/models/boards reload for the new project, and the URL does **not** change to `/<project_name>` (no document request in the Network tab).
2. Pick the **same** project → nothing happens (no reload, no overlay).
3. A failing switch (backend error) now shows a toast instead of silently aborting.
4. `PinnedProjectsSwitcher` (same store action) keeps working with identical behaviour.

